const box = (x, y, width, height) => ({ x, y, width, height });
const pixelBox = (b, canvas) => ({ x: Math.round(b.x * canvas.width), y: Math.round(b.y * canvas.height), width: Math.round(b.width * canvas.width), height: Math.round(b.height * canvas.height) });
const text = (inputKey, bounds, options = {}) => {
  const role = options.role;
  const defaultSizeRatio = role === "headline" ? 0.46 : role === "supporting" ? 0.30 : role === "cta" ? 0.28 : role === "brand" ? 0.30 : role === "contact" ? 0.24 : 0.23;
  const { sizeRatio = defaultSizeRatio, ...rest } = options;
  return { type: "text", inputKey, box: box(...bounds), editable: true, scale: 1, align: "left", maxLines: 2, sizeRatio, ...rest };
};
const image = (inputKey, bounds, mask, options = {}) => { const { kind = "image_slot", ...rest } = options; return { type: kind, inputKey, box: box(...bounds), editable: true, fit: "cover", mask, shape: mask === "ellipse" ? "circle" : mask, ...rest }; };
const vector = (inputKey, bounds, shape, options = {}) => { const { kind = "vector_patch", ...rest } = options; return { type: kind, inputKey, box: box(...bounds), editable: true, shape, ...rest }; };
const icon = (inputKey, bounds, shape, options = {}) => ({ type: "vector_icon", inputKey, box: box(...bounds), editable: true, shape, ...options });
const slot = (inputKey, bounds, options = {}) => ({ type: "logo_slot", inputKey, box: box(...bounds), editable: true, ...options });
const overlay = (inputKey, bounds, role) => ({ type: "overlay_patch", inputKey, box: box(...bounds), editable: true, role: `story-backing-${role}`, colourRole: "story-backing", colour: "#f4f0e8" });
