const finalizePlacement = (placement, canvas, records) => {
  const orderedRecords = placement === "story" ? (() => {
    const supportingIndex = records.findIndex((record) => record.inputKey === "backing-supporting");
    const ctaIndex = records.findIndex((record) => record.inputKey === "backing-cta");
    if (supportingIndex >= 0 && ctaIndex > supportingIndex) {
      const reordered = [...records];
      const [ctaBacking] = reordered.splice(ctaIndex, 1);
      reordered.splice(supportingIndex, 0, ctaBacking);
      return reordered;
    }
    return records;
  })() : records;
  return Object.freeze(orderedRecords.map((record, index) => Object.freeze({ ...record, id: placement + "-" + record.inputKey, z: index + 1, pixelBox: pixelBox(record.box, canvas) })));
};
function makeInputs(id, entry) {
  const sampleValues = { ...samples, ...(sampleOverridesById[id] || {}) };
  const imageInputs = [{ key: "customer_photo", kind: "image", label: "Primary property photo", required: true, sample: "SOURCE-FREE FIXTURE SLOT" }];
  for (let index = 1; index < entry.images; index += 1) imageInputs.push({ key: `property_image_${index}`, kind: "image", label: `Supporting property photo ${index}`, required: true, sample: "SOURCE-FREE FIXTURE SLOT" });
  imageInputs.push({ key: "logo_slot", kind: "logo", label: "Brand logo", required: false, sample: "SOURCE-FREE LOGO SLOT" });
  if (entry.portrait) imageInputs.push({ key: "portrait_slot", kind: "portrait", label: "Agent portrait", required: false, sample: "SOURCE-FREE PORTRAIT SLOT" });
  const textKeys = ["brand_name", "headline", "supporting", ...entry.semantics, "cta", "contact"];
  const textInputs = [...new Set(textKeys)].map((key) => ({ key, kind: "text", label: key.replaceAll("_", " "), required: true, maxLength: key === "cta" ? 28 : 48, sample: sampleValues[key] || "EDITABLE DETAIL" }));
  const vectorInputs = ["background_patch", "surface_patch", "accent_patch", "decor_primary", "icon_primary", ...EXTRA_VECTORS[id]];
  return { images: imageInputs, text: textInputs, vectors: vectorInputs.map((key) => ({ key, kind: "vector", label: key.replaceAll("_", " "), required: true, editable: true })) };
}

// The original v2 plans above remain as the historical contract fixture.  The
// launch surfaces use these authored compositions: every geometry decision is
// explicit, but the small helpers keep the layer records legible and uniform.
const polishedVector = (inputKey, bounds, shape, options = {}) => {
  const { kind = "vector_patch", role = shape, colourRole = "accent", ...rest } = options;
  return vector(inputKey, bounds, shape, { kind, role, colourRole, ...rest });
};
const polishedImage = (inputKey, bounds, mask, role, options = {}) => image(inputKey, bounds, mask, { kind: "image_slot", role, ...options });
const polishedText = (inputKey, bounds, role, font, colourRole, options = {}) => text(inputKey, bounds, { role, font, colourRole, ...options });
const polishedBrand = (font, colourRole = "ink", bounds = [0.08, 0.075, 0.25, 0.034]) => polishedText("brand_name", bounds, "brand", font, colourRole, { maxLines: 1 });
const polishedLogo = (bounds = [0.75, 0.075, 0.17, 0.04]) => slot("logo_slot", bounds, { fit: "contain", mask: "rect", role: "brand-mark", shape: "rect" });
const polishedBackground = (shape = "rect", role = "background") => polishedVector("background_patch", [0, 0, 1, 1], shape, { role, colourRole: "background" });
const polishedSurface = (bounds, shape, role, colourRole = "surface") => polishedVector("surface_patch", bounds, shape, { role, colourRole });
const polishedDecor = (bounds, shape = "line", role = "layout-rule", colourRole = "accent", options = {}) => polishedVector("decor_primary", bounds, shape, { kind: "vector_decor", role, colourRole, ...options });
const polishedCta = (options = {}) => {
  const {
    x = 0.66, y = 0.88, width = 0.27, height = 0.05, shape = "rounded",
    colourRole = "accent", copyColourRole = "inverseText", contactX = 0.08,
    contactWidth = 0.34, contactY, iconShape = "line",
  } = options;
  const resolvedContactY = contactY ?? y + 0.014;
  return [
    polishedVector("accent_patch", [x, y, width, height], shape, { role: "cta-button", colourRole }),
    polishedText("cta", [x + 0.032, y + 0.014, width - 0.085, 0.022], "cta", "sans-bold", copyColourRole, { maxLines: 1 }),
    polishedText("contact", [contactX, resolvedContactY, contactWidth, 0.022], "contact", "sans", copyColourRole, { maxLines: 1 }),
    icon("icon_primary", [x + width - 0.046, y + 0.011, 0.03, 0.03], iconShape, { role: "cta_icon", colourRole }),
  ];
};

